import numpy as np


class Solver:
    def solve(self, problem, **kwargs) -> np.ndarray:
        vec1, vec2 = problem
        # Use broadcasting directly: avoids np.outer's overhead of
        # ravel(), asarray() calls, and extra Python-level checks.
        # vec1[:, None] creates a column view, vec2 is a row — multiply broadcasts.
        return np.asarray(vec1).ravel()[:, None] * np.asarray(vec2).ravel()
